    --g-btn-height: 2rem;
    --g-btn-padding-x: 0.9375rem;
    display: inline-flex;
    inline-size: auto;
    min-inline-size: 0;
    block-size: var(--g-btn-height);
    min-block-size: var(--g-btn-height);
    align-items: center;
    justify-content: center;
    gap: var(--g-btn-icon-gap, .5rem);
    padding: 0 var(--g-btn-padding-x);
    border: var(--g-border-width) solid var(--g-btn-border);
    border-radius: var(--g-basic-radius, 2px);
    background: var(--g-btn-bg);
